insert into posts(author_id,media_type,title,caption,tags,storage_key,thumb_key,media_url,thumbnail_url,status,script) select author_id,'art','StyleGenius News — Friday, November 6, 2026','StyleGenius News — Friday, November 6, 2026',array['stylegeniusnews','episode'],storage_key,thumb_key,media_url,thumbnail_url,'live',$J${"segments": [{"broll": [{"src": "/sgn/hosts/both-original-master-navy-suit-and-red-dress-at-the-desk.jpg", "caption": "Goldie Rush and Suki Crow at the StyleGenius News desk."}], "lines": [{"host": "Goldie Rush", "text": "Welcome back to StyleGenius News. It\u2019s Friday, which means the culture just handed us six reasons to stay online past midnight. Billie went full latex, Olivia went full Christmas, and the robots at Vogue World made Miuccia Prada look personally offended. We\u2019re covering all of it.", "img": "/sgn/hosts/goldie-navy-suit.jpg"}, {"host": "Suki Crow", "text": "Goldie, I just portal-jumped from a timeline where the latex was still drying and the Christmas song was already number one. If this is the Friday energy, I\u2019m not coming back down.", "img": "/sgn/hosts/suki-cream-floral.jpg"}, {"host": "Goldie Rush", "text": "Sit. We\u2019ve got six minutes and the internet is already losing it.", "img": "/sgn/hosts/goldie-hand-out.jpg"}]}, {"broll": [{"src": "/sgn/broll/2026-11-06/seg1-a.jpg", "caption": "Billie Eilish at Icebox, November 2018 (archive photo).", "credit": "Icebox \u2014 CC BY 3.0. Source: https://commons.wikimedia.org/wiki/File:Billie_Eilish_at_Icebox.png. License: https://creativecommons.org/licenses/by/3.0. Resized and JPEG converted."}], "lines": [{"host": "Goldie Rush", "text": "Lead story. Billie Eilish stepped out today in a bright blue bob and head-to-toe latex. Not a look. A full material takeover.", "img": "/sgn/hosts/goldie-chalk-pinstripe.jpg"}, {"host": "Suki Crow", "text": "That latex isn\u2019t clothing, it\u2019s a second skin with better lighting. The blue bob is so sharp it looks like it was cut by the same algorithm that designs fighter jets. Gorillaz bass player already co-signed. When the band starts approving the fit, you know the culture has officially surrendered.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "So the rule is now: if it\u2019s latex and it\u2019s blue, it\u2019s canon?", "img": "/sgn/hosts/goldie-navy-suit.jpg"}, {"host": "Suki Crow", "text": "The rule is if Billie wears it, the rest of us are just late.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [{"src": "/sgn/broll/2026-11-06/seg2-a.jpg", "caption": "Olivia Rodrigo performing at Glastonbury, 2025 (archive photo).", "credit": "Raph_PH \u2014 CC BY 4.0. Source: https://commons.wikimedia.org/wiki/File:Olivia_Rodrigo_2.jpeg. License: https://creativecommons.org/licenses/by/4.0. Resized and JPEG converted."}], "lines": [{"host": "Goldie Rush", "text": "Meanwhile, Olivia Rodrigo just dropped \u201cTake Me Home (4 Christmas).\u201d First holiday song. Red Santa hat, matching lipstick, sitting on the floor like she owns December.", "img": "/sgn/hosts/goldie-hand-out.jpg"}, {"host": "Suki Crow", "text": "She didn\u2019t ease into the holidays, she kicked the door down with a single. The internet is already making heatless-curl tutorials to the melody. That\u2019s how you know it\u2019s working. One song and suddenly everyone\u2019s hair is in a no-heat spiral while they argue about whether this counts as a Christmas album or a warning.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "So the countdown to December just started in November. Classic.", "img": "/sgn/hosts/goldie-chalk-pinstripe.jpg"}, {"host": "Suki Crow", "text": "It\u2019s not early. It\u2019s efficient. The rest of the industry is still deciding on a color palette.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [{"src": "/sgn/broll/2026-11-06/seg3-a.jpg", "caption": "Humanoid robot at an exhibition; contextual robotics image, not Vogue World.", "credit": "Om Umekar \u2014 CC BY-SA 4.0. Source: https://commons.wikimedia.org/wiki/File:Humanoid_Robot_at_International_Exhibitions.jpg. License: https://creativecommons.org/licenses/by-sa/4.0. Resized and JPEG converted."}], "lines": [{"host": "Goldie Rush", "text": "Tech segment. Vogue World Milan closed with actual walking robots. OpenAI and Meta were sponsors. Miuccia Prada and Alessandro Michele looked like they\u2019d just seen the future and wanted a refund.", "img": "/sgn/hosts/goldie-navy-suit.jpg"}, {"host": "Suki Crow", "text": "The robots walked better than some models, and that is the problem. At the same time, Prada just released a fully hand-animated holiday campaign. Real artists. Real drawing. The message is clear: human-made is the new luxury. AI can generate the look, but it can\u2019t generate the story people want to keep.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "So the algorithm gets the runway and the human gets the campaign.", "img": "/sgn/hosts/goldie-hand-out.jpg"}, {"host": "Suki Crow", "text": "For now. Give it six months and the algorithm is going to want the campaign too.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [{"src": "/sgn/broll/2026-11-06/seg4-a.jpg", "caption": "Bad Bunny in Los Angeles, October 2019 (archive photo).", "credit": "Glenn Francis / PacificProDigital.com (Toglenn) \u2014 CC BY-SA 4.0. Source: https://commons.wikimedia.org/wiki/File:Bad_Bunny_2019_by_Glenn_Francis.jpg. License: https://creativecommons.org/licenses/by-sa/4.0. Resized and JPEG converted."}], "lines": [{"host": "Suki Crow", "text": "Luxury drop alert. Bad Bunny and adidas are bringing two new BadBo styles on November 12. That\u2019s next week. The internet is already treating it like a limited-edition watch drop.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "Sneakers with that much cultural weight now move like high jewelry. Meanwhile, the broader conversation is that the new AI billionaires are dressing better than the old tech uniform, and brands are noticing. When the money changes, the silhouette changes.", "img": "/sgn/hosts/goldie-chalk-pinstripe.jpg"}, {"host": "Suki Crow", "text": "Exactly. The next luxury flex isn\u2019t a logo. It\u2019s whether the thing was touched by a human or just rendered. Bad Bunny\u2019s drop is still human-led hype, and that\u2019s why it\u2019s about to sell out before the robots even finish their walk.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [{"src": "/sgn/broll/2026-11-06/seg5-a.jpg", "caption": "Television remote control; contextual viewing image.", "credit": "Dmitry Makeev \u2014 CC BY-SA 4.0. Source: https://commons.wikimedia.org/wiki/File:Television_remote_control_-_black_01.jpg. License: https://creativecommons.org/licenses/by-sa/4.0. Resized and JPEG converted."}], "lines": [{"host": "Goldie Rush", "text": "Friday streaming. Fire Country and Sheriff Country are doing the crossover. Will Estes is back on Boston Blue. And the micro-trend holding everything together is heatless curls plus holiday drinks. The culture wants comfort and chaos at the same time.", "img": "/sgn/hosts/goldie-navy-suit.jpg"}, {"host": "Suki Crow", "text": "Which brings us to the StyleGenius Award. This week it goes to Billie Eilish. Not for the blue bob. Not for the latex. For proving that one look can still stop the entire internet in 2026. In a week of robots, holiday songs, and AI campaigns, she just put on the material and walked. That\u2019s the award.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "Billie Eilish. StyleGenius Award. Accepted by the culture.", "img": "/sgn/hosts/goldie-hand-out.jpg"}, {"host": "Suki Crow", "text": "And probably by the latex manufacturer.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [], "lines": [{"host": "Both", "text": "StyleGenius News\u2026 because reality is overrated. Sponsored by Don De Juan.", "img": "/sgn/hosts/both-original-master-navy-suit-and-red-dress-at-the-desk.jpg"}]}, {"broll": [], "lines": [{"host": "Suki Crow", "text": "Okay, but if the robots start wearing the blue latex next week, I\u2019m blaming you for manifesting it.", "img": "/sgn/hosts/suki-blue-floral.jpg"}, {"host": "Goldie Rush", "text": "I didn\u2019t manifest it. I just reported it. The portal is still open if you want to check the timeline.", "img": "/sgn/hosts/goldie-chalk-pinstripe.jpg"}, {"host": "Suki Crow", "text": "I\u2019m good. I\u2019m keeping the smoothie and the award energy. See you Monday.", "img": "/sgn/hosts/suki-cream-floral.jpg"}]}, {"broll": [], "lines": [{"host": "Both", "text": "StyleGenius News, because reality's overrated. Sponsored by Don De Juan.", "img": "/sgn/hosts/both-original-master-navy-suit-and-red-dress-at-the-desk.jpg"}]}]}$J$::jsonb from posts where author_id=(select id from profiles where username='stylegeniusnews') order by created_at asc limit 1 returning id;